query:
query issueEventsAndAssociatedObjectsByHierarchyBreakdown(
  $details: IssueDetails!
  $hierarchyLevel: HierarchyLevelInput!
) {
  issueEventsAndAssociatedObjectsByHierarchyBreakdown(
    details: $details
    hierarchyLevel: $hierarchyLevel
  ) {
    label
    items {
      label
      value
    }
  }
}
